    const add = EventTarget.prototype.addEventListener, rem = EventTarget.prototype.removeEventListener;
    EventTarget.prototype.addEventListener = function (type, fn, o) { if (isGlobal(this)) { const k = type; globalLive.set(k, (globalLive.get(k) || 0) + 1); } return add.call(this, type, fn, o); };
